  1	/**
  2	 * Math Formula Plugin
  3	 *
  4	 * Supports inline formulas (`$...$`) and block formulas (```math ... ```)
  5	 * Uses KaTeX for rendering, supports edit mode switching
  6	 *
  7	 * How it works:
  8	 * 1. Traverse syntax tree to find math formula nodes
  9	 * 2. Decide whether to show rendered result or source based on cursor position
 10	 * 3. Use Widget for rendering, use Mark decoration for edit mode
 11	 *
 12	 * Note:
 13	 * - Inline formulas use ViewPlugin (Decoration.replace without block)
 14	 * - Block formulas use StateField (block decorations must be provided via StateField)
 15	 */
 16	
 17	import { syntaxTree } from '@codemirror/language';
 18	import { EditorState, Range, StateField } from '@codemirror/state';
 19	import {
 20	  Decoration,
 21	  DecorationSet,
 22	  EditorView,
 23	  ViewPlugin,
 24	  ViewUpdate,
 25	} from '@codemirror/view';
 26	import { shouldShowSource } from '../core/shouldShowSource';
 27	import { mouseSelectingField } from '../core/mouseSelecting';
 28	import { checkUpdateAction } from '../core/pluginUpdateHelper';
 29	import { createMathWidget } from '../widgets/mathWidget';
 30	
 31	/**
 32	 * Inline math formula ViewPlugin
 33	 *
 34	 * Handles `$...$` format inline formulas
 35	 */
 36	export const mathPlugin = ViewPlugin.fromClass(
 37	  class {
 38	    decorations: DecorationSet;
 39	
 40	    constructor(view: EditorView) {
 41	      this.decorations = this.build(view);
 42	    }
 43	
 44	    update(update: ViewUpdate) {
 45	      if (checkUpdateAction(update) === 'rebuild') {
 46	        this.decorations = this.build(update.view);
 47	      }
 48	    }
 49	
 50	    build(view: EditorView): DecorationSet {
 51	      const decorations: Range<Decoration>[] = [];
 52	      const { state } = view;
 53	      const isDrag = state.field(mouseSelectingField, false);
 54	
 55	      syntaxTree(state).iterate({
 56	        enter: (node) => {
 57	          // Only handle inline formulas
 58	          if (node.name === 'InlineCode') {
 59	            const fullText = state.doc.sliceString(node.from, node.to);
 60	
 61	            if (
 62	              fullText.startsWith('`$') &&
 63	              fullText.endsWith('$`') &&
 64	              fullText.length > 4
 65	            ) {
 66	              const source = fullText.slice(2, -2);
 67	              const isTouched = shouldShowSource(state, node.from, node.to);
 68	
 69	              if (!isTouched && !isDrag) {
 70	                const widget = createMathWidget(source, false);
 71	                decorations.push(
 72	                  Decoration.replace({ widget }).range(node.from, node.to)
 73	                );
 74	              } else {
 75	                decorations.push(
 76	                  Decoration.mark({ class: 'cm-math-source' }).range(
 77	                    node.from,
 78	                    node.to
 79	                  )
 80	                );
 81	              }
 82	            }
 83	          }
 84	        },
 85	      });
 86	
 87	      return Decoration.set(decorations.sort((a, b) => a.from - b.from), true);
 88	    }
 89	  },
 90	  {
 91	    decorations: (v) => v.decorations,
 92	  }
 93	);
 94	
 95	/**
 96	 * Build block math formula decorations
 97	 */
 98	function buildBlockMathDecorations(state: EditorState): DecorationSet {
 99	  const decorations: Range<Decoration>[] = [];
100	  const isDrag = state.field(mouseSelectingField, false);
101	
102	  syntaxTree(state).iterate({
103	    enter: (node) => {
104	      if (node.name === 'FencedCode') {
105	        const codeInfo = node.node.getChild('CodeInfo');
106	        if (codeInfo) {
107	          const lang = state.doc.sliceString(codeInfo.from, codeInfo.to);
108	
109	          if (lang === 'math') {
110	            const codeText = node.node.getChild('CodeText');
111	            const source = codeText
112	              ? state.doc.sliceString(codeText.from, codeText.to).trim()
113	              : '';
114	            const isTouched = shouldShowSource(state, node.from, node.to);
115	
116	            if (!isTouched && !isDrag) {
117	              // Show rendered result
118	              const widget = createMathWidget(source, true);
119	              decorations.push(
120	                Decoration.replace({ widget, block: true }).range(
121	                  node.from,
122	                  node.to
123	                )
124	              );
125	            } else {
126	              // Edit mode: add background to each line
127	              for (let pos = node.from; pos <= node.to; ) {
128	                const line = state.doc.lineAt(pos);
129	                decorations.push(
130	                  Decoration.line({ class: 'cm-math-source-block' }).range(
131	                    line.from
132	                  )
133	                );
134	                pos = line.to + 1;
135	              }
136	            }
137	          }
138	        }
139	      }
140	    },
141	  });
142	
143	  return Decoration.set(decorations.sort((a, b) => a.from - b.from), true);
144	}
145	
146	/**
147	 * Block math formula StateField
148	 *
149	 * Handles ```math ... ``` format block formulas
150	 * Must use StateField because block decorations cannot be provided via ViewPlugin
151	 */
152	export const blockMathField = StateField.define<DecorationSet>({
153	  create(state) {
154	    return buildBlockMathDecorations(state);
155	  },
156	
157	  update(deco, tr) {
158	    if (tr.docChanged || tr.reconfigured) {
159	      return buildBlockMathDecorations(tr.state);
160	    }
161	
162	    const isDragging = tr.state.field(mouseSelectingField, false);
163	    const wasDragging = tr.startState.field(mouseSelectingField, false);
164	
165	    if (wasDragging && !isDragging) {
166	      return buildBlockMathDecorations(tr.state);
167	    }
168	
169	    if (isDragging) {
170	      return deco;
171	    }
172	
173	    if (tr.selection) {
174	      return buildBlockMathDecorations(tr.state);
175	    }
176	
177	    return deco;
178	  },
179	
180	  provide: (f) => EditorView.decorations.from(f),
181	});

