 1	/**
 2	 * Math Formula Render Cache
 3	 *
 4	 * Avoids re-rendering identical formulas, improves performance
 5	 */
 6	
 7	/**
 8	 * Render cache
 9	 * Key format: "inline:formula" or "block:formula"
10	 */
11	const cache = new Map<string, string>();
12	
13	/**
14	 * Render math formula
15	 *
16	 * @param source - Formula source (without $ symbols)
17	 * @param displayMode - true = block formula, false = inline formula
18	 * @returns Rendered HTML string
19	 *
20	 * @example
21	 * ```typescript
22	 * renderMath('E = mc^2', false) // Inline formula
23	 * renderMath('\\int_0^\\infty e^{-x^2} dx', true) // Block formula
24	 * ```
25	 */
26	export function renderMath(source: string, displayMode: boolean): string {
27	  const key = `${displayMode ? 'block' : 'inline'}:${source}`;
28	
29	  if (cache.has(key)) {
30	    return cache.get(key)!;
31	  }
32	
33	  // Dynamic import KaTeX (user may not have installed)
34	  try {
35	    // @ts-expect-error - KaTeX is peer dependency
36	    const katex = window.katex;
37	
38	    if (!katex) {
39	      throw new Error('KaTeX not found. Please install katex package.');
40	    }
41	
42	    const rendered = katex.renderToString(source, {
43	      displayMode,
44	      throwOnError: false,
45	      errorColor: '#cc0000',
46	      strict: false,
47	    });
48	
49	    cache.set(key, rendered);
50	    return rendered;
51	  } catch (error) {
52	    const errorMsg = error instanceof Error ? error.message : 'Unknown error';
53	    return `<span class="cm-math-error">[Math Error: ${errorMsg}]</span>`;
54	  }
55	}
56	
57	/**
58	 * Clear render cache
59	 *
60	 * Call when KaTeX version updates or config changes
61	 */
62	export function clearMathCache(): void {
63	  cache.clear();
64	}

