 1	/**
 2	 * Math Formula Widget
 3	 *
 4	 * Uses KaTeX to render math formulas, supports inline and block modes
 5	 */
 6	
 7	import { WidgetType } from '@codemirror/view';
 8	import { renderMath } from '../utils/mathCache';
 9	
10	/**
11	 * Math Formula Widget class
12	 *
13	 * Responsible for rendering math formulas to DOM elements
14	 */
15	export class MathWidget extends WidgetType {
16	  /**
17	   * @param source - Formula source (without $ symbols)
18	   * @param isBlock - Whether it's a block formula
19	   */
20	  constructor(
21	    readonly source: string,
22	    readonly isBlock: boolean
23	  ) {
24	    super();
25	  }
26	
27	  /**
28	   * Check if two widgets are equal
29	   *
30	   * Used for optimization: skip re-render if equal
31	   */
32	  eq(other: MathWidget): boolean {
33	    return other.source === this.source && other.isBlock === this.isBlock;
34	  }
35	
36	  /**
37	   * Render to DOM element
38	   */
39	  toDOM(): HTMLElement {
40	    const container = document.createElement(this.isBlock ? 'div' : 'span');
41	    container.className = this.isBlock ? 'cm-math-block' : 'cm-math-inline';
42	
43	    try {
44	      const rendered = renderMath(this.source, this.isBlock);
45	      container.innerHTML = rendered;
46	    } catch (error) {
47	      const errorMsg = error instanceof Error ? error.message : 'Unknown error';
48	      container.textContent = `[Math Error: ${errorMsg}]`;
49	      container.className += ' cm-math-error';
50	    }
51	
52	    return container;
53	  }
54	
55	  /**
56	   * Whether to ignore events
57	   *
58	   * Return false to allow click to enter edit mode
59	   */
60	  ignoreEvent(): boolean {
61	    return false;
62	  }
63	}
64	
65	/**
66	 * Create math formula widget
67	 *
68	 * @param source - Formula source (without $ symbols)
69	 * @param isBlock - Whether it's a block formula
70	 * @returns MathWidget instance
71	 */
72	export function createMathWidget(source: string, isBlock: boolean): MathWidget {
73	  return new MathWidget(source, isBlock);
74	}

