 1	import { ViewUpdate } from '@codemirror/view';
 2	import { mouseSelectingField } from './mouseSelecting';
 3	
 4	/**
 5	 * Update action for ViewPlugin
 6	 * - 'rebuild': Decorations need to be rebuilt
 7	 * - 'skip': Skip this update (e.g., during drag)
 8	 * - 'none': No action needed
 9	 */
10	export type UpdateAction = 'rebuild' | 'skip' | 'none';
11	
12	/**
13	 * Determine what action a ViewPlugin should take on update
14	 *
15	 * This helper extracts the common update logic shared by livePreviewPlugin
16	 * and mathPlugin, handling:
17	 * 1. Document/viewport/config changes → rebuild
18	 * 2. Drag end → rebuild
19	 * 3. During drag → skip (avoid flickering)
20	 * 4. Selection change → rebuild
21	 *
22	 * @param update - The ViewUpdate from CodeMirror
23	 * @returns The action the plugin should take
24	 *
25	 * @example
26	 * ```typescript
27	 * update(update: ViewUpdate) {
28	 *   const action = checkUpdateAction(update);
29	 *   if (action === 'rebuild') {
30	 *     this.decorations = this.build(update.view);
31	 *   }
32	 * }
33	 * ```
34	 */
35	export function checkUpdateAction(update: ViewUpdate): UpdateAction {
36	  // Document/viewport/config changes: must rebuild
37	  if (
38	    update.docChanged ||
39	    update.viewportChanged ||
40	    update.transactions.some((t) => t.reconfigured)
41	  ) {
42	    return 'rebuild';
43	  }
44	
45	  // Check drag state
46	  const isDragging = update.state.field(mouseSelectingField, false);
47	  const wasDragging = update.startState.field(mouseSelectingField, false);
48	
49	  // Just finished dragging: rebuild
50	  if (wasDragging && !isDragging) {
51	    return 'rebuild';
